.sb-popup-cls{
	height: 14px;
	width: 14px;
	position: absolute;
	cursor: pointer;
	right: 17px;
	top: 17px;
	z-index: 3;
}
.sb-center-boss{
	display: flex;
	justify-content: center;
	align-items: center;
}
.sb-popup-inside{
	left: 80px;
	width: 880px;
	max-width: calc(100% - 200px);
	background: #fff;
	color: #141B38;
	position: relative;
	box-shadow: 0px 26.7377px 77.2886px rgba(0, 0, 0, 0.107828), 0px 14.2952px 41.3222px rgba(0, 0, 0, 0.0894161), 0px 8.01379px 23.1649px rgba(0, 0, 0, 0.075), 0px 4.25607px 12.3027px rgba(0, 0, 0, 0.0605839), 0px 1.77104px 5.11942px rgba(0, 0, 0, 0.0421718);
	border-radius: 2px;
	overflow-y: auto;
	max-height: 80vh;
}
.sb-popup-inside.sb-narrower-modal {
	max-width: 576px;
}
.sb-popup-inside.sb-onboarding-tooltip {
	overflow-y: visible !important;
}
@media all and (max-width: 960px) {
	.sb-popup-inside {
		left: 20px;
		width: 100%;
		max-width: calc(100% - 100px);
	}
}

/* Install Plugin Modal on Select Source Flow */
.sb-btn-orange{
	background: #FE544F!important;
	color: #fff!important;
}
.sb-btn-orange:hover{
	background: #EC352F!important;
	border-color: #EC352F!important;
	color: #fff!important;
}
.sb-btn-orange:focus,
.sb-btn-orange:active{
	background: #BC120E!important;
	border-color: #BC120E!important;
	color: #fff!important;
}

/*red*/
.sb-btn-blue{
	background: #0068A0!important;
	color: #fff!important;
}
.sb-btn-blue:hover{
	background: #0096CC!important;
	border-color: #0096CC!important;
	color: #fff!important;
}
.sb-btn-blue:focus,
.sb-btn-blue:active{
	background: #004D77!important;
	border-color: #004D77!important;
	color: #fff!important;
}
.sb-fs-boss{
	position: fixed;
	height: 100vh;
	width: 100%;
	left: 0;
	top: 0;
	bottom: 0;
	right: 0;
	background: rgba(0,0,0,.4);
	z-index: 9989;
}
.sb-install-plugin-modal {
	max-width: 580px;
}
.sb-install-plugin-body .sb-install-plugin-header {
	height: 106px;
	background: #F3F4F5;
	padding: 20px;
	display: flex;
	box-sizing: border-box;
    flex-wrap: wrap;
    align-items: center;
}
.sb-install-plugin-body .sb-install-plugin-header .sb-plugin-image {
	background-color: #fff;
    box-shadow: 0px 1px 2px rgb(0 0 0 / 5%), 0px 4px 5px rgb(0 0 0 / 5%);
    border-radius: 2px;
    padding: 15px;
    max-height: 66px;
    box-sizing: border-box;
	margin-right: 24px;
}
.sb-install-plugin-body .sb-install-plugin-header h3 {
	font-size: 18px !important;
	line-height: 25px !important;
	display: flex;
    align-items: center;
    text-transform: capitalize;
}
.sb-install-plugin-body .sb-install-plugin-header h3 span {
	color: #fff;
	background: #59AB46;
	border-radius: 2px;
	font-size: 10px;
	line-height: 16px;
	letter-spacing: 0.08em;
	text-transform: uppercase;
	padding: 0px 6px;
	margin-left: 10px;
}
.sb-install-plugin-body .sb-install-plugin-header p {
	display: flex;
	font-size: 12px;
	line-height: 18px;
	color: #434960;
	margin: 5px 0 0 0;
}
.sb-install-plugin-body .sb-install-plugin-header p .sb-author-logo {
	margin-right: 8px;
}

.sb-install-plugin-body .sb-install-plugin-content {
	padding: 20px 20px 32px 107px;
}
.sb-install-plugin-body .sb-install-plugin-content p {
	margin: 0px;
	font-size: 14px;
	line-height: 22px;
	color: #434960;
    padding-right: 20px;
}
.sb-install-plugin-body .sb-install-plugin-content .sb-plugin-btn {
	display: flex;
	align-items: center;
	justify-content: center;
	height: 38px;
	padding: 8px 20px;
	box-sizing: border-box;
	transition: all .15s ease-in-out;
	border-radius: 2px;
	width: 100%;
	margin-top: 28px;
	border: none;
	font-size: 14px;
	font-weight: 600;
	line-height: 160%;
	cursor: pointer;
}
.sb-install-plugin-body .sb-install-plugin-content .sb-btn-orange:disabled {
	color: #8C8F9A !important;
	background: #E8E8EB !important;
	cursor: not-allowed;
}
.sb-install-plugin-body .sb-install-plugin-content .sb-plugin-btn span {
	height: 20px;
	width: 20px;
	margin-right: 5px;
}
.sb-mr-fd-list button {
	cursor: pointer;
}
.sb-plugin-name strong{
	color: #434960;
	text-transform: uppercase;
}
.sb-plugin-image{
	border-radius: 13px !important;
    -webkit-transform: rotate(-3deg);
    transform: rotate(-3deg);
}
.sb-plugin-image svg{
	-webkit-transform: rotate(3deg);
    transform: rotate(3deg);
}

.sb-plugin-cta-logo {
	position: absolute;
	right: -11px;
	bottom: -10px;
	z-index: 1;
}

